<?php
/** Native paid history, permanent deletion, retired-modern owner and quarantine survive B. */
declare(strict_types=1);
require __DIR__.'/support/reset-retirement.php';
use RodolfoRizzo\Cpt2Collection\{TableNames,TransactionManager,ProviderRegistry,OrderDeletionService,OrderDeletionRepository,OrderDeletionRegistry,UtcClock,PaymentSessionRepository};
$db=new wpdb('c2c_b_evidence_'.bin2hex(random_bytes(5)).'_');$t=new TableNames($db);try{
 validation_schema($db);$old=validation_order($db,1);$tx=new TransactionManager($db,$t);$delete=new OrderDeletionService(new OrderDeletionRepository($db,$t),new OrderDeletionRegistry($db,$t),$tx,new UtcClock());check($delete->delete($old['order'])->code()==='deleted','retired-modern fixture uses actual permanent deletion');baseline_epoch_switch($db);
 $f=validation_order($db,1);
 check($tx->begin_commerce_shared(),'second attempt native evidence admitted');$sessions=new PaymentSessionRepository($db,$t);check($sessions->mark_failed($f['session'],gmdate('Y-m-d H:i:s')),'original attempt releases active slot');$next=$sessions->create_attempt(bin2hex(random_bytes(16)),$f['order'],'stripe_checkout',hash('sha256','second'),'EUR',100,gmdate('Y-m-d H:i:s'));$claim=$db->get_row("SELECT * FROM {$t->provider_claims()} WHERE id={$f['claim']}");$p=json_decode($claim->request_snapshot,true);$p['reference']=$next->reference();$p['idempotency_key']='c2c_ps_'.$next->reference();$registry=new ProviderRegistry($db,$t);check(is_object($registry->create_claim($next,$tx->commerce_context(),json_encode($p),'test',gmdate('Y-m-d H:i:s')))&&$tx->commit(),'multiple native claims for one order');check($delete->delete($f['order'])->code()==='deleted','all source claims permanently deleted with exact tombstones');$event=validation_receipt($db,$f,'evt_deleted_late');
 validation_receipt($db,$f,'evt_quarantine');check($tx->begin_commerce_shared(),'quarantine fixture admitted');check($registry->bind('stripe_checkout','event','evt_quarantine',$old['claim'],gmdate('Y-m-d H:i:s'),hash('sha256','original'),'checkout.session.completed','test')==='bound','original old owner retained');check($registry->bind('stripe_checkout','event','evt_quarantine',$f['claim'],gmdate('Y-m-d H:i:s'),hash('sha256','conflict'),'checkout.session.completed','test')==='conflict'&&$tx->commit(),'conflicting source observation quarantined');
 // Valid durable custom conflict evidence must survive B's receipt-binding path too.
 sql($db,"UPDATE {$t->provider_identities()} SET conflict_code='retained_conflict' WHERE identity_value='evt_quarantine'");
 $foreign=$db->get_row("SELECT * FROM {$t->provider_claims()} WHERE id={$old['claim']}");$deleted=$db->get_results("SELECT * FROM {$t->provider_claims()} WHERE order_id={$f['order']} ORDER BY id");$quarantine=$db->get_row("SELECT * FROM {$t->provider_identities()} WHERE identity_value='evt_quarantine'");
 // Actual payment establishes a processed Event and physical stock before reset.
