 $r=validation_pass($db,validation_start($db));$before=retirement_preserved($db);$r=retirement_pass($db,$r,1);check($r->phase()==='deleting','paid, deleted, retired-modern and quarantined evidence all reach deleting');
 check(get_object_vars($foreign)===get_object_vars($db->get_row("SELECT * FROM {$t->provider_claims()} WHERE id={$old['claim']}")),'foreign retired-modern claim unchanged');check(serialize($deleted)===serialize($db->get_results("SELECT * FROM {$t->provider_claims()} WHERE order_id={$f['order']} ORDER BY id")),'multiple deleted source claims preserve disposition and original tombstone');check(get_object_vars($quarantine)===get_object_vars($db->get_row("SELECT * FROM {$t->provider_identities()} WHERE identity_value='evt_quarantine'")),'quarantine retains original owner, conflict code and disposition');check($db->get_var("SELECT disposition FROM {$t->provider_identities()} WHERE identity_value='evt_paid_b'")==='processed','meaningful processed Event disposition preserved');check($calls===$old_calls,'B performs zero provider calls');check($before===retirement_preserved($db),'historical sale stock and all operational receipts retained without reset mutation');
}finally{baseline_cleanup($db);}
